-- =====================================================================
-- Seed: the 31 films from the Excel sheet (Sep 2026).
-- Run AFTER schema.sql, once, in Supabase → SQL Editor.
-- Excel "Yes"/"Done" → Done, blank → Pending, "Expected today" kept as is.
-- =====================================================================
on conflict (sno) do nothing;

-- make the next new video get S.NO 32 (max + 1)
select setval(pg_get_serial_sequence('public.videos','sno'), (select coalesce(max(sno),0) from public.videos));
